import heapq
from itertools import count

def virtual_loop(jobs):
    def job(delays):
        for delay in delays:
            yield delay              # plays the part of 'await asyncio.sleep(delay)'

    order = count()                  # FIFO tie-break for equal wake-up times
    queue = [(0, next(order), name, job(delays)) for name, delays in jobs]
    heapq.heapify(queue)
    trace = []
    while queue:
        now, _, name, coro = heapq.heappop(queue)
        trace.append([now, name])
        try:
            delay = next(coro)       # run the job until its next 'await'
        except StopIteration:
            continue                 # the job returned
        heapq.heappush(queue, (now + delay, next(order), name, coro))
    return trace

