import heapq

def pool_schedule(durations, workers):
    free_at = [0] * min(workers, len(durations))   # a heap of times each worker frees up
    spans = []
    for duration in durations:
        start = free_at[0]                          # earliest-free worker takes the next task
        heapq.heapreplace(free_at, start + duration)
        spans.append([start, start + duration])
    makespan = max((end for _, end in spans), default=0)
    return {'spans': spans, 'makespan': makespan}

